import{_ as n,o as t,c as i,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const c=JSON.parse('{"title":"Teilleistungen vorbereiten und erfassen","description":"","frontmatter":{},"headers":[],"relativePath":"zeugnisse/teilleistungen.md","filePath":"zeugnisse/teilleistungen.md"}'),r={name:"zeugnisse/teilleistungen.md"};function l(a,e,u,h,g,d){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="teilleistungen-vorbereiten-und-erfassen" tabindex="-1">Teilleistungen vorbereiten und erfassen <a class="header-anchor" href="#teilleistungen-vorbereiten-und-erfassen" aria-label="Permalink to &quot;Teilleistungen vorbereiten und erfassen&quot;">​</a></h1><p>Teilleistungen speichern Einzel- oder Zwischenleistungen zusätzlich zur Zeugnisnote. Bereiten Sie Arten und Zuordnung vor, bevor Sie Noten eingeben.</p><h2 id="teilleistungen-einrichten" tabindex="-1">Teilleistungen einrichten <a class="header-anchor" href="#teilleistungen-einrichten" aria-label="Permalink to &quot;Teilleistungen einrichten&quot;">​</a></h2><p>Nutzen Sie die Anleitung <a href="/schild3/schueler/teilleistungen-einrichten-und-verwalten-tutorial.html">Teilleistungen einrichten, erfassen und ausgeben</a>. Der Katalog <a href="/schild3/unterricht-kataloge/teilleistungs-arten-schulbezogene-kataloge.html">Teilleistungsarten</a> stellt die schulinternen Arten bereit.</p><h2 id="die-passende-zuweisung-wahlen" tabindex="-1">Die passende Zuweisung wählen <a class="header-anchor" href="#die-passende-zuweisung-wahlen" aria-label="Permalink to &quot;Die passende Zuweisung wählen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Fach- und kursartbezogene Vorlagen übernehmen</td><td><a href="/schild3/suchen-gruppenprozesse/teilleistungsarten-aus-vorlage-zuweisen-gruppenprozesse-teilleistungen.html">Teilleistungen aus Vorlage</a></td></tr><tr><td>Teilleistungsarten für einzelne Fach-/Kursarten wählen</td><td><a href="/schild3/suchen-gruppenprozesse/teilleistungsarten-individuell-zuweisen-gruppenprozesse-teilleistungen.html">Teilleistungen individuell</a></td></tr><tr><td>Eine Teilleistungsart allen Fächern zuweisen</td><td><a href="/schild3/suchen-gruppenprozesse/teilleistungsarten-global-zuweisen-gruppenprozesse-teilleistungen.html">Teilleistungsarten global</a></td></tr></tbody></table><p>Die globale Zuweisung betrifft alle Fächer der ausgewählten Schülerinnen und Schüler. Für einzelne Fach-/Kursart-Kombinationen verwenden Sie die individuelle Zuweisung.</p><h2 id="noten-erfassen-und-eintrage-entfernen" tabindex="-1">Noten erfassen und Einträge entfernen <a class="header-anchor" href="#noten-erfassen-und-eintrage-entfernen" aria-label="Permalink to &quot;Noten erfassen und Einträge entfernen&quot;">​</a></h2><p>Mit <a href="/zeugnisse/vorbereitung/noteneingabe-nur-vorbereitete-tl-gruppenprozesse-teilleistungen.html">Noten für vorbereitete Teilleistungen eingeben</a> füllen Sie vorbereitete Einträge. Der Gruppenprozess <a href="/schild3/suchen-gruppenprozesse/teilleistungen-fuer-einen-abschnitt-loeschen-gruppenprozesse-teilleistungen.html">Teilleistungen eines Lernabschnitts löschen</a> entfernt alle Teilleistungen des gewählten Abschnitts für die ausgewählte Gruppe und ist entsprechend sorgfältig anzuwenden.</p><p>Für Prüfungen beachten Sie zusätzlich <a href="/zeugnisse/zp10.html">ZP10 und Zentrale Klausuren</a> oder <a href="/zeugnisse/berufskolleg.html">BK-Abschluss</a>.</p>',10)])])}const p=n(r,[["render",l]]);export{c as __pageData,p as default};
